static int index_step_size (int size) {

    if (size == DATA_CHAR || size == DATA_SHORT || size == DATA_INT ||
        size == DATA_LONG || size == DATA_LLONG || size == DATA_FLOAT ||
        size == DATA_DOUBLE) {
        return size & 0x1f;
    }
    
    if (size <= 0) {
        return DATA_INT & 0x1f;
    }
    
    return size;

}

