static int amd64_member_layout_alignment (int size) {

    size &= 0x1f;
    
    if (size >= (DATA_PTR & 0x1f)) {
        return DATA_PTR & 0x1f;
    }
    
    if (size >= (DATA_INT & 0x1f)) {
        return DATA_INT & 0x1f;
    }
    
    if (size >= (DATA_SHORT & 0x1f)) {
        return DATA_SHORT & 0x1f;
    }
    
    return 1;

}

static int amd64_align_member_offset (int offset, int align) {

    if (align <= 1) {
        return offset;
    }
    
    return (offset + align - 1) & ~(align - 1);

}

static int amd64_member_owner_matches (int mi, int owner_size, const char *owner_tag_name) {

    if (member_infos[mi].owner_size != owner_size) {
        return 0;
    }
    
    if (owner_tag_name && owner_tag_name[0]) {
        return member_infos[mi].owner_tag_name && strcmp (member_infos[mi].owner_tag_name, owner_tag_name) == 0;
    }
    
    return member_infos[mi].owner_tag_name == 0;

}

static int amd64_relayout_aggregate_members (int owner_size, const char *owner_tag_name, const char *typedef_name) {

    int mi;
    int offset = 0;
    int max_align = 1;
    int matched = 0;
    
    /*
     * Fix the aggregate layout metadata itself instead of rounding member
     * offsets at every access site.  The parser's old i386 layout rules used
     * 4-byte alignment for pointer-sized fields.  On AMD64 the member table
     * must record the real 8-byte-aligned offsets so every later access,
     * initializer, copy, and typedef lookup sees the same layout.
     */
    for (mi = 0; mi < member_info_count; mi++) {
    
        int size;
        int align;
        
        if (!amd64_member_owner_matches (mi, owner_size, owner_tag_name)) {
            continue;
        }
        
        if (member_infos[mi].is_packed) {
        
            matched = 1;
            continue;
        
        }
        
        size = member_infos[mi].is_array ? member_infos[mi].size : (member_infos[mi].size & 0x1f);
        
        if (size <= 0) {
            size = DATA_INT & 0x1f;
        }
        
        /*
         * An array has the alignment of its element type, not the
         * alignment implied by the array's total storage size.  Using
         * size here made, for example, unsigned short reserved[4]
         * eight-byte aligned on AMD64 and shifted every following member.
         */
        align = amd64_member_layout_alignment (member_infos[mi].is_array ? member_infos[mi].elem_size : size);
        
        if (align > max_align) {
            max_align = align;
        }
        
        offset = amd64_align_member_offset (offset, align);
        member_infos[mi].offset = offset;
        
        offset += size;
        matched++;
    
    }
    
    if (!matched) {
        return owner_size;
    }
    
    if (offset == 0) {
    
        for (mi = 0; mi < member_info_count; mi++) {
        
            if (!amd64_member_owner_matches (mi, owner_size, owner_tag_name)) {
                continue;
            }
            
            if (!member_infos[mi].owner_tag_name && typedef_name && typedef_name[0]) {
                member_infos[mi].owner_tag_name = xstrdup (typedef_name);
            }
        
        }
        
        return owner_size;
    
    }
    
    offset = amd64_align_member_offset (offset, max_align);
    
    for (mi = 0; mi < member_info_count; mi++) {
    
        if (!amd64_member_owner_matches (mi, owner_size, owner_tag_name)) {
            continue;
        }
        
        member_infos[mi].owner_size = offset;
        
        if (!member_infos[mi].owner_tag_name && typedef_name && typedef_name[0]) {
            member_infos[mi].owner_tag_name = xstrdup (typedef_name);
        }
    
    }
    
    return offset;

}

static int find_member_info (const char *name, int *offset, int *size) {
    return find_member_info_ex (name, offset, size, 0, 0, 0, 0);
}

static void clear_typedef_names (void) {

    int i;
    
    for (i = 0; i < typedef_name_count; i++) {
    
        free (typedef_names[i].name);
        
        typedef_names[i].name = 0;
        typedef_names[i].size = 0;
        
        typedef_names[i].tag_name = 0;
        
        typedef_names[i].is_aggregate = 0;
        typedef_names[i].is_unsigned = 0;
        
        typedef_names[i].field_count = 0;
        typedef_names[i].is_array = 0;
        typedef_names[i].array_count = 1;
        typedef_names[i].array_element_size = DATA_NONE;
        
        typedef_names[i].calling_convention = TOK_EOF;
    
    }
    
    typedef_name_count = 0;

}

static void save_typedef_name (const char *name, int size, int is_unsigned, int is_void, int is_aggregate, int is_array, long array_count, int array_element_size, enum token_kind calling_convention, const int *field_sizes, int field_count) {

    struct typedef_entry *entry;
    int i;
    
    if (!name || !*name) {
        return;
    }
    
    if (is_aggregate && !is_array) {
    
        const char *owner_tag_name = parsed_type_tag_name[0] ? parsed_type_tag_name : 0;
        int fixed_size = amd64_relayout_aggregate_members (size, owner_tag_name, name);
        
        if (fixed_size > 0) {
            size = fixed_size;
        }
    
    }
    
    entry = find_typedef_name (name);
    
    if (!entry) {
    
        if (typedef_name_count >= MAX_TYPEDEF_NAMES) {
        
            report_line_at (get_filename (), get_line_number (), REPORT_ERROR, tok.report_start, tok.report_caret, "too many typedef names");
            return;
        
        }
        
        entry = &typedef_names[typedef_name_count++];
        entry->name = xstrdup (name);
        entry->tag_name = 0;
        entry->calling_convention = TOK_EOF;
    
    }
    
    if (entry->tag_name) {
    
        free (entry->tag_name);
        entry->tag_name = 0;
    
    }
    
    if (parsed_type_tag_name[0]) {
        entry->tag_name = xstrdup (parsed_type_tag_name);
    } else if (is_aggregate && name && *name) {
        entry->tag_name = xstrdup (name);
    }
    
    entry->is_void = is_void;
    entry->size = size;
    
    entry->is_unsigned = is_unsigned;
    entry->is_aggregate = is_aggregate;
    
    entry->field_count = 0;
    entry->is_array = is_array ? 1 : 0;
    entry->array_count = array_count > 0 ? array_count : 1;
    entry->array_element_size = array_element_size > 0 ? array_element_size : DATA_INT;
    entry->calling_convention = calling_convention;
    
    for (i = 0; i < field_count && i < MAX_AGG_FIELDS; i++) {
        entry->field_sizes[entry->field_count++] = field_sizes[i];
    }
    
    if (is_aggregate && !parsed_type_tag_name[0] && name && *name) {
    
        int mi;
        
        for (mi = 0; mi < member_info_count; mi++) {
        
            if (member_infos[mi].owner_size == size && member_infos[mi].owner_tag_name == 0) {
                member_infos[mi].owner_tag_name = xstrdup (name);
            }
        
        }
    
    }

}

